* {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      background: #0a0e1a;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      font-family: 'Orbitron', monospace;
      margin: 0;
      padding: 16px;
    }

    .cyber-char-component {
      background: #0d1225;
      border: 3px solid #00f0ff;
      box-shadow: 0 0 20px rgba(0, 240, 255, 0.3), inset 0 0 30px rgba(0, 240, 255, 0.05);
      padding: 28px 24px 24px 24px;
      max-width: 820px;
      width: 100%;
      border-radius: 8px;
      position: relative;
      overflow: hidden;
    }

    .cyber-char-component::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: repeating-linear-gradient(0deg, rgba(0, 240, 255, 0.02) 0px, rgba(0, 240, 255, 0.02) 2px, transparent 2px, transparent 6px);
      pointer-events: none;
      z-index: 1;
    }

    .cyber-char-component .cyber-divider {
      width: 100%;
      height: 3px;
      background: linear-gradient(90deg, transparent, #00f0ff, #ff00e6, #00f0ff, transparent);
      margin: 16px 0 20px 0;
      box-shadow: 0 0 12px #00f0ff88;
      position: relative;
      z-index: 2;
    }

    .cyber-char-component .cyber-title {
      font-weight: 900;
      font-size: 14px;
      letter-spacing: 3px;
      color: #00f0ff;
      text-shadow: 0 0 10px #00f0ff, 0 0 30px #00f0ff66;
      margin-bottom: 12px;
      display: flex;
      align-items: center;
      gap: 14px;
      flex-wrap: wrap;
      position: relative;
      z-index: 2;
    }

    .cyber-char-component .cyber-title .badge {
      background: rgba(0, 240, 255, 0.12);
      border: 1px solid #00f0ff88;
      padding: 4px 12px;
      font-size: 10px;
      color: #ff00e6;
      text-shadow: 0 0 8px #ff00e688;
      letter-spacing: 2px;
    }


    .cyber-char-component .char-display {
      background: #060a18;
      border: 2px solid #00f0ff55;
      padding: 24px 16px;
      text-align: center;
      margin: 8px 0 16px 0;
      box-shadow: inset 0 0 40px rgba(0, 240, 255, 0.05), 0 0 30px rgba(0, 240, 255, 0.05);
      border-radius: 4px;
      position: relative;
      z-index: 2;
      min-height: 110px;
      display: flex;
      justify-content: center;
      align-items: center;
    }


    .cyber-char-component .char-display .char-wrapper {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
      justify-content: center;
    }

    .cyber-char-component .char-display .char-slot {
      font-weight: 900;
      font-size: clamp(32px, 7vw, 58px);
      line-height: 1.3;
      color: #00f0ff;
      text-shadow: 0 0 20px #00f0ff, 0 0 60px #00f0ff44;
      transition: color 0.2s, text-shadow 0.3s;
      font-family: 'Orbitron', monospace;
      min-width: 0.6em;
      text-align: center;
      display: inline-block;
    }


    .cyber-char-component .char-display .char-slot.frozen {
      color: #ff00e6;
      text-shadow: 0 0 30px #ff00e6, 0 0 80px #ff00e688, 0 0 120px #ff00e644;
      animation: cyberPulse 1.2s ease-in-out infinite alternate;
    }

    @keyframes cyberPulse {
      0% { opacity: 0.9; transform: scale(1); text-shadow: 0 0 30px #ff00e6, 0 0 80px #ff00e688; }
      100% { opacity: 1; transform: scale(1.03); text-shadow: 0 0 50px #ff00e6, 0 0 120px #ff00e6aa, 0 0 200px #ff00e644; }
    }


    .cyber-char-component .param-panel {
      background: rgba(0, 240, 255, 0.04);
      border: 1px solid #00f0ff44;
      padding: 12px 16px;
      margin-top: 16px;
      border-radius: 4px;
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 12px 24px;
      position: relative;
      z-index: 2;
    }

    .cyber-char-component .param-panel .param-item {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 11px;
      color: #6ec8ff;
    }

    .cyber-char-component .param-panel .param-item .label {
      background: rgba(0, 240, 255, 0.08);
      padding: 2px 10px;
      border: 1px solid #00f0ff44;
      color: #00f0ff;
      font-size: 9px;
      letter-spacing: 1px;
      text-transform: uppercase;
    }

    .cyber-char-component .param-panel .param-item .value {
      background: #060a18;
      padding: 2px 12px;
      border: 1px solid #00f0ff33;
      color: #b0eaff;
      font-size: 13px;
      font-weight: 700;
      min-width: 30px;
      text-align: center;
    }


    .cyber-char-component .status-bar {
      margin-top: 20px;
      display: flex;
      align-items: center;
      gap: 14px;
      position: relative;
      z-index: 2;
    }

    .cyber-char-component .status-bar .bar-track {
      flex: 1;
      height: 10px;
      background: #060a18;
      border: 1px solid #00f0ff55;
      box-shadow: inset 0 0 10px rgba(0, 240, 255, 0.1);
      position: relative;
      overflow: hidden;
      border-radius: 2px;
    }

    .cyber-char-component .status-bar .bar-fill {
      height: 100%;
      width: 0%;
      background: linear-gradient(90deg, #00f0ff, #ff00e6, #00f0ff);
      background-size: 200% 100%;
      animation: cyberBarShine 1.5s linear infinite;
      box-shadow: 0 0 20px #00f0ff66;
      transition: width 0.1s ease;
    }

    @keyframes cyberBarShine {
      0% { background-position: 0% 0%; }
      100% { background-position: 200% 0%; }
    }

    .cyber-char-component .status-bar .bar-label {
      font-size: 12px;
      font-weight: 700;
      color: #00f0ff;
      text-shadow: 0 0 8px #00f0ff66;
      min-width: 56px;
      text-align: right;
      letter-spacing: 1px;
    }


    .cyber-char-component .cyber-btn {
      background: transparent;
      border: 2px solid #00f0ff;
      color: #00f0ff;
      font-family: 'Orbitron', monospace;
      font-weight: 700;
      font-size: 13px;
      padding: 12px 20px;
      margin-top: 20px;
      cursor: pointer;
      text-shadow: 0 0 8px #00f0ff66;
      box-shadow: 0 0 20px rgba(0, 240, 255, 0.1), inset 0 0 20px rgba(0, 240, 255, 0.05);
      transition: all 0.2s ease;
      letter-spacing: 2px;
      width: 100%;
      text-align: center;
      border-radius: 4px;
      position: relative;
      z-index: 2;
      background: rgba(0, 240, 255, 0.03);
    }

    .cyber-char-component .cyber-btn:hover {
      background: rgba(0, 240, 255, 0.08);
      box-shadow: 0 0 40px rgba(0, 240, 255, 0.2), inset 0 0 30px rgba(0, 240, 255, 0.1);
      border-color: #ff00e6;
      color: #ff00e6;
      text-shadow: 0 0 20px #ff00e688;
    }

    .cyber-char-component .cyber-btn:active {
      transform: scale(0.97);
    }

    .cyber-char-component .cyber-btn:disabled {
      opacity: 0.6;
      cursor: not-allowed;
      transform: none;
      border-color: #00f0ff55;
      color: #00f0ff77;
      box-shadow: none;
    }

    .cyber-char-component .footnote {
      font-size: 8px;
      color: #00f0ff44;
      margin-top: 16px;
      text-align: center;
      letter-spacing: 3px;
      border-top: 1px solid #00f0ff22;
      padding-top: 14px;
      position: relative;
      z-index: 2;
    }

    @media (max-width: 480px) {
      .cyber-char-component .char-display .char-slot {
        font-size: clamp(22px, 5vw, 34px);
      }
      .cyber-char-component .char-display .char-wrapper {
        gap: 3px;
      }
      .cyber-char-component .param-panel {
        flex-direction: column;
        align-items: stretch;
        gap: 8px;
      }
    }

component.script:
(function() {



      const finalChar = '$finalChar$' || 'CYBER';
      const strLength = finalChar.length;


      const baseChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>?/~';
      const cyberChars = '⍟✦✧★☆⚡☯⚔⊛⟡';
      const charSet = baseChars + cyberChars;


      const cyclesPerChar = Math.max(6, Math.min(16, 12 - strLength + 4));

      const charInterval = 70;

      const freezeDelay = 180;




      const wrapper = document.getElementById('charWrapper');
      const progressFill = document.getElementById('progressFill');
      const progressLabel = document.getElementById('progressLabel');
      const triggerBtn = document.getElementById('triggerBtn');
      const paramFinalSpan = document.getElementById('paramFinalChar');
      const paramLengthSpan = document.getElementById('paramLength');
      const statusDisplay = document.getElementById('statusDisplay');

      paramFinalSpan.textContent = finalChar;
      paramLengthSpan.textContent = strLength;




      let isRunning = false;
      let allTimers = [];
      let charElements = [];
      let frozenCount = 0;
      let isComplete = false;


      function getRandomChar() {
        const idx = Math.floor(Math.random() * charSet.length);
        return charSet[idx] || '?';
      }


      function generateRandomString(length) {
        let result = '';
        for (let i = 0; i < length; i++) {
          result += getRandomChar();
        }
        return result;
      }


      function clearAllTimers() {
        allTimers.forEach(t => clearTimeout(t));
        allTimers = [];
        allTimers.forEach(t => clearInterval(t));
        allTimers = [];
      }


      function stopAnimation() {
        clearAllTimers();
        isRunning = false;
        triggerBtn.disabled = false;
        if (isComplete) {
          triggerBtn.textContent = '⟳ REBOOT';
        } else {
          triggerBtn.textContent = '⟳ INITIALIZE';
        }
      }




      function startAnimation() {

        stopAnimation();
        clearAllTimers();
        wrapper.innerHTML = '';
        charElements = [];
        frozenCount = 0;
        isComplete = false;
        isRunning = true;

        triggerBtn.disabled = true;
        triggerBtn.textContent = '⧗ RUNNING...';
        statusDisplay.textContent = '⧗';
        progressFill.style.width = '0%';
        progressLabel.textContent = '0%';


        const chars = finalChar.split('');
        const initialRandom = generateRandomString(strLength).split('');

        chars.forEach((finalCh, index) => {
          const span = document.createElement('span');
          span.className = 'char-slot';

          span.textContent = initialRandom[index] || getRandomChar();
          span.dataset.index = index;
          span.dataset.final = finalCh;
          span.dataset.frozen = 'false';
          wrapper.appendChild(span);
          charElements.push(span);
        });



        charElements.forEach((el, idx) => {
          let cycleCount = 0;
          const totalCycles = cyclesPerChar + idx * 2; 


          const startDelay = idx * 60;

          let timer = setTimeout(function tick() {
            if (!isRunning) return;


            if (el.dataset.frozen === 'true') return;


            el.textContent = getRandomChar();
            cycleCount++;


            if (cycleCount >= totalCycles) {

              el.textContent = el.dataset.final;
              el.dataset.frozen = 'true';
              el.classList.add('frozen');
              frozenCount++;


              const progress = frozenCount / strLength;
              const percent = Math.round(progress * 100);
              progressFill.style.width = percent + '%';
              progressLabel.textContent = percent + '%';
              statusDisplay.textContent = Math.round(progress * 100) + '%';


              if (frozenCount === strLength) {
                isComplete = true;
                isRunning = false;
                triggerBtn.disabled = false;
                triggerBtn.textContent = '⟳ REBOOT';
                statusDisplay.textContent = '✦';
                progressFill.style.width = '100%';
                progressLabel.textContent = '100%';
              }
              return;
            }


            const nextDelay = charInterval + Math.random() * 30;
            timer = setTimeout(tick, nextDelay);
          }, startDelay);

          allTimers.push(timer);
        });


        const safetyCheck = setInterval(function() {
          if (frozenCount === strLength && !isComplete) {
            isComplete = true;
            isRunning = false;
            triggerBtn.disabled = false;
            triggerBtn.textContent = '⟳ REBOOT';
            statusDisplay.textContent = '✦';
            progressFill.style.width = '100%';
            progressLabel.textContent = '100%';
            clearInterval(safetyCheck);
          }
        }, 300);
        allTimers.push(safetyCheck);
      }




      triggerBtn.addEventListener('click', function(e) {
        if (isRunning) {

          stopAnimation();

          wrapper.innerHTML = '';
          charElements = [];
          frozenCount = 0;
          isComplete = false;
          progressFill.style.width = '0%';
          progressLabel.textContent = '0%';
          statusDisplay.textContent = '⏳';
          triggerBtn.textContent = '⟳ INITIALIZE';

          setTimeout(() => {
            startAnimation();
          }, 200);
        } else {
          startAnimation();
        }
      });




      window.addEventListener('load', function() {
        setTimeout(function() {
          if (!isRunning && triggerBtn) {
            startAnimation();
          }
        }, 500);
      });

      console.log('[Cyber] finalChar="' + finalChar + '" length=' + strLength + ' cyclesPerChar=' + cyclesPerChar);
    })();
